DEFAULT_FALLBACK = "M12 3v10.55c-.59-.34-1.27-.55-2-.55-2.21 0-4 1.79-4 4s1.79 4 4 4 4-1.79 4-4V7h4V3h-6z"

corrupted_path = "M12,2A10,10 0 0,0 2,12A10,10 0 0,0 12,22A10,10 0 0,0 22,12A10,10 0 0,0 12,2M12,4A8,8 0 0,1 20,12A8,8 0 0,1 12,20A8,8 0 0,1 4,12A8,8 0 0,1 12,4M11,6V14L16.5,10.75L11,6Z"

drawable_dir = "app/src/main/res/drawable"
updated = 0

for fname in os.listdir(drawable_dir):
    if not fname.endswith(".xml"):
        continue
    fpath = os.path.join(drawable_dir, fname)
    with open(fpath, "r", encoding="utf-8", errors="ignore") as f:
        content = f.read()
    
    if corrupted_path in content:
        name = fname[:-4]
        # Look for matching icon
        path = ICONS.get(name)
        if not path:
            # Try removing ic_ prefix or finding partial match
            alt_name = name.replace("ic_", "")
            path = ICONS.get(alt_name)
        if not path:
            path = DEFAULT_FALLBACK
        
        new_content = f'''<?xml version="1.0" encoding="utf-8"?>
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="24dp"
    android:height="24dp"
    android:viewportWidth="24"
    android:viewportHeight="24">
    <path
        android:fillColor="#FFFFFFFF"
        android:pathData="{path}" />
</vector>
'''
        with open(fpath, "w", encoding="utf-8") as f:
            f.write(new_content)
        updated += 1

print(f"Successfully fixed {updated} vector icons.")
